from live_evidence.cli import _prepare_replay_session


class Response:
    def __init__(self, payload):
        self._payload = payload

    def raise_for_status(self):
        return None

    def json(self):
        return self._payload


class Client:
    def __init__(self, snapshot):
        self.snapshot = snapshot
        self.posts = []

